async function bill_detilDelete(self, body) {
	const { source, id } = body 
	const req = self.req
	const user_id = req.session.user.userId
	const startTime = process.hrtime.bigint()
	const tablename = detilTableName

	try {

		const data_timestamp = (new Date()).toISOString()

		const deletedRow = await db.tx(async tx=>{
			sqlUtil.connect(tx)

			const dataToRemove = {billdetil_id: id}
			const sql = `select * from ${detilTableName} where billdetil_id=\${billdetil_id}`
			const rowdetil = await tx.oneOrNone(sql, dataToRemove)

			const logMetadata = {}

			// apabila ada keperluan pengelohan data sebelum dihapus, lakukan di extender
			if (typeof Extender.detilDeleting === 'function') {
				// export async function detilDeleting(self, tx, rowdetil, logMetadata) {}
				await Extender.detilDeleting(self, tx, rowdetil, logMetadata)
			}

			const param = {billdetil_id: rowdetil.billdetil_id}
			const cmd = sqlUtil.createDeleteCommand(detilTableName, ['billdetil_id'])
			const deletedRow = await cmd.execute(param)


			// update timestamp pada header
			tx.none(`update ${headerTableName} set _timestamp=$[_timestamp] where ${headerPrimaryKey}=$[pk]`, {
				_timestamp: data_timestamp,
				pk: rowdetil.bill_id
			})

			// apabila ada keperluan pengelohan data setelah dihapus, lakukan di extender
			if (typeof Extender.detilDeleted === 'function') {
				// export async function detilDeleted(self, tx, deletedRow, logMetadata) {}
				await Extender.detilDeleted(self, tx, deletedRow, logMetadata)
			}					

			bill_log(self, body, startTime, detilTableName, rowdetil.billdetil_id, 'DELETE', {rowdata: deletedRow})
			bill_log(self, body, startTime, headerTableName, rowdetil.bill_id, 'DELETE ROW DETIL', {billdetil_id: rowdetil.billdetil_id, tablename: detilTableName}, `removed: ${rowdetil.billdetil_id}`)

			return deletedRow
		})
	

		return deletedRow
	} catch (err) {
		throw err
	}
}

async function bill_detilDeleteRows(self, body) {
	const { data } = body 
	const req = self.req
	const user_id = req.session.user.userId
	const startTime = process.hrtime.bigint();
	const tablename = detilTableName


	try {


		const data_timestamp = (new Date()).toISOString()

		let bill_id
		const result = await db.tx(async tx=>{
			sqlUtil.connect(tx)

			for (let id of data) {
				const dataToRemove = {billdetil_id: id}
				const sql = `select * from ${detilTableName} where billdetil_id=\${billdetil_id}`
				const rowdetil = await tx.oneOrNone(sql, dataToRemove)
				bill_id = rowdetil.bill_id

				const logMetadata = {}

				
				// apabila ada keperluan pengelohan data sebelum dihapus, lakukan di extender
				if (typeof Extender.detilDeleting === 'function') {
					// async function detilDeleting(self, tx, rowdetil, logMetadata) {}
					await Extender.detilDeleting(self, tx, rowdetil, logMetadata)
				}

				const param = {billdetil_id: rowdetil.billdetil_id}
				const cmd = sqlUtil.createDeleteCommand(detilTableName, ['billdetil_id'])
				const deletedRow = await cmd.execute(param)

				// update timestamp pada header
				tx.none(`update ${headerTableName} set _timestamp=$[_timestamp] where ${headerPrimaryKey}=$[pk]`, {
					_timestamp: data_timestamp,
					pk: rowdetil.bill_id
				})
				
				// apabila ada keperluan pengelohan data setelah dihapus, lakukan di extender
				if (typeof Extender.detilDeleted === 'function') {
					// export async function detilDeleted(self, tx, deletedRow, logMetadata) {}
					await Extender.detilDeleted(self, tx, deletedRow, logMetadata)
				}					

				bill_log(self, body, startTime, detilTableName, rowdetil.billdetil_id, 'DELETE', {rowdata: deletedRow})
				bill_log(self, body, startTime, headerTableName, rowdetil.bill_id, 'DELETE ROW DETIL', {billdetil_id: rowdetil.billdetil_id, tablename: detilTableName}, `removed: ${rowdetil.billdetil_id}`)
			}
		})
		

		const res = {
			deleted: true,
			bill_id: bill_id,
			message: ''
		}

		// apabila ada keperluan update info / pemrosesan data setelah hapus multirow, lakukan di extender
		const fn_name = 'detilRowsDeleted'
		const fn = Extender[fn_name]
		if (typeof fn === 'function') {
			// export async function detilRowsDeleted(self, db, res) {}
			await fn(self, db, res)
		}

		return res
	} catch (err) {
		throw err
	}	
}

	